'use strict';
const $ = s => document.querySelector(s);
const canvas=$('#scene'), ctx=canvas.getContext('2d');
const ui={menu:$('#menuScreen'),modal:$('#modalScreen'),modalCard:$('#modalCard'),status:$('#status'),action:$('#actionBtn'),toast:$('#toast'),area:$('#areaLabel'),catch:$('#catchCount'),cash:$('#cash'),rod:$('#rodName'),tension:$('#tensionUI'),fill:$('#tensionFill'),tensionLabel:$('#tensionLabel')};
const areas=[
 ['Toxic Bay','A neon-green shoreline crawling with glow bugs.'],['Rustwater Docks','Shipwreck pilings hide sharp-toothed scavengers.'],['Mushroom Marsh','Spore clouds drift over the bubbling bog.'],['Glassbone Reef','Prismatic coral cuts through electric-blue tides.'],['Sunken Suburb','Porch lights still flicker beneath the waves.'],['Frostbite Fjord','Frozen brine. Something huge moves below.'],['Volcano Trench','Lava vents keep the deep strangely warm.'],['Moonfall Lake','Meteor shards make the fish glow silver.'],['The Void','No sun. No bottom. No ordinary fish.'],['Zanrich Expanse','The final waters. The legend is waiting.']
];
const fishNames=[
 ['Glooper','Trashfin','Sewer Guppy','Glowbelly','Bay Brute'],['Boltjaw','Tin Can Carp','Rust Pike','Dock Creeper','Harbor Hulk'],['Spore Minnow','Mushroom Muncher','Bogglider','Toadstool Trout','Marsh Maw'],['Prism Perch','Glass Goby','Shardfin','Coral Creeper','Reef Ripper'],['Porchlight Perch','Mailbox Mullet','TV-Head Bass','Suburb Squid','The Landlord'],['Frostbitten Fry','Ice Pick Pike','Snowblind Salmon','Glacier Eel','Fjordfather'],['Cinder Carp','Magma Minnow','Ashen Angler','Lava Lurker','Caldera King'],['Comet Koi','Moon Mothfish','Stardust Sturgeon','Orbit Octopus','Lunar Leviathan'],['Null Nibbler','Darkmatter Dace','Eclipse Eel','Nightmare Ray','The Unmaker'],['Zanling','Zanrich Fry','Zanrich Herald','Zanrich Prime','ZANRICH']
];
const rods=[['Junker',0,1],['Bottle Rocket',90,1.12],['Rebar Rod',180,1.25],['Glowstick Pro',320,1.4],['Turbo Tackle',520,1.58],['Deep Diver',780,1.78],['Wyrm Whip',1100,2],['Stormcaller',1500,2.25],['Void Harpoon',2000,2.55],['Zanrich Bane',2800,2.9]];
let fishList=[]; areas.forEach((a,zone)=>fishNames[zone].forEach((name,j)=>fishList.push({name,zone,boss:j===4,index:zone*5+j,rarity:j===4?'BOSS':['COMMON','UNCOMMON','RARE','EPIC'][j],value:25+zone*18+j*13+(j===4?180:0),size:18+zone*4+j*9}));
const saveKey='mutant-monster-fishing-v1';
let save; try{save=JSON.parse(localStorage.getItem(saveKey))||{cash:120,caught:[],rods:[0],rod:0,area:0,story:0,duels:0};}catch{save={cash:120,caught:[],rods:[0],rod:0,area:0,story:0,duels:0};}
let mode='free',phase='idle',currentFish=null,progress=0,tension=0,biteAt=0,phaseAt=0,holding=false,challengeCatches=0,duelScore=0,botScore=0,lastTime=0,elapsed=0,toastTimer=0;
let W=0,H=0,dpr=1,particles=[];
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function persist(){localStorage.setItem(saveKey,JSON.stringify(save));updateHUD();}
function updateHUD(){ui.catch.textContent=save.caught.length;ui.cash.textContent=save.cash;ui.rod.textContent=rods[save.rod][0].toUpperCase();ui.area.textContent=`${areas[save.area][0].toUpperCase()} · ${mode.toUpperCase()}${mode==='story'?' · CHAPTER '+(save.story+1):''}`;}
function toast(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2100);}
function resize(){const r=$('#game').getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);}
window.addEventListener('resize',resize);resize();
function openMenu(){holding=false;ui.menu.classList.remove('hidden');ui.modal.classList.add('hidden');phase='idle';ui.tension.style.display='none';ui.action.textContent='CAST';updateHUD();}
function startGame(which){mode=which;ui.menu.classList.add('hidden');ui.modal.classList.add('hidden');phase='idle';progress=tension=0;challengeCatches=0;duelScore=botScore=0;updateHUD();setStatus(`${mode==='story'?'Chapter '+(save.story+1)+': ':''}Cast into ${areas[save.area][0]} and see what bites.`);}
function setStatus(text){ui.status.innerHTML=text;}
function cast(){if(phase==='idle'){phase='waiting';phaseAt=elapsed;biteAt=elapsed+2.6+Math.random()*3.2;progress=tension=0;currentFish=null;ui.action.textContent='WAIT…';setStatus('Line is out…<br><span style="color:#a8b99a">Watch for a bite, then reel!</span>');return;} if(phase==='waiting'){toast('Let the bait sink…');return;} if(phase==='bite'){phase='reeling';phaseAt=elapsed;progress=0;tension=20;ui.tension.style.display='block';ui.action.textContent='REEL!';setStatus('A MUTANT BIT! Hold REEL and keep the line in the green.');toast('BITE! REEL NOW!');return;} if(phase==='reeling'){holding=!holding;}}
function loseFish(reason){phase='idle';holding=false;ui.tension.style.display='none';ui.action.textContent='CAST';setStatus(`${reason}<br><span style="color:#a8b99a">Cast again when ready.</span>`);toast(reason);}
function chooseFish(){let pool=fishList.filter(f=>f.zone===save.area);let bossChance=mode==='challenge'?0.15:0.11;if(Math.random()<bossChance)return pool[4];let top=save.area*5+3;let candidates=fishList.filter(f=>f.zone<=save.area&&f.index<top&&!f.boss);return candidates[Math.floor(Math.random()*candidates.length)]||pool[0];}
function landFish(){const f=currentFish;phase='idle';holding=false;ui.tension.style.display='none';ui.action.textContent='CAST';save.caught=[...new Set([...save.caught,f.index])];save.cash+=f.value;challengeCatches++;if(mode==='pvp'){duelScore++;if(duelScore>=3){save.duels++;toast(`DUEL WON! ${duelScore} – ${botScore}`);mode='free';}else toast(`NICE CATCH! ${duelScore} – ${botScore}`);}else toast(`${f.boss?'BOSS LANDED! ':'CAUGHT! '}${f.name} +${f.value}¢`);
 if(f.boss&&save.area<9){save.area=Math.max(save.area,Math.min(9,save.area+1));toast(`BOSS BEATEN! ${areas[save.area][0]} unlocked!`);}
 if(mode==='story'&&challengeCatches>=3){save.story=Math.min(9,save.story+1);toast('CHAPTER COMPLETE! New waters await.');}
 if(mode==='challenge'&&challengeCatches>=3){toast('CHALLENGE COMPLETE! 3 mutant catches!');mode='free';}
 if(mode==='pvp'&&duelScore<3){setStatus(`<b>${f.name}</b> landed! Rival score ${botScore}. Cast for the next round.`);} else setStatus(`<b>${f.name}</b> · ${f.rarity} · ${f.size} cm<br><span style="color:#a8b99a">${f.boss?'Boss defeated!':'Sold for '+f.value+'¢'} · Cast again!</span>`);
 if(mode==='pvp'&&duelScore<3){} else if(mode==='story')setStatus(`${f.name} landed! ${Math.max(0,3-challengeCatches)} more for this chapter.<br><span style="color:#a8b99a">Cast to continue the story.</span>`);
 persist();}
$('#actionBtn').addEventListener('pointerdown',e=>{e.preventDefault();if(phase==='bite')cast();else if(phase==='reeling')holding=true;else cast();});
window.addEventListener('pointerup',()=>holding=false);
$('#actionBtn').addEventListener('contextmenu',e=>e.preventDefault());
$('#menuBtn').addEventListener('click',openMenu);
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>startGame(b.dataset.mode)));

