document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{
 const m=b.dataset.mode;
 if(m==='story'&&save.story>=10){toast('Story complete! Replay the final chapter.');save.story=9;persist();}
 if(m==='challenge')toast('Challenge: land 3 fish in a row!');
 if(m==='pvp')toast('First to 3 catches wins the duel!');
 startGame(m);
}));
function showModal(title,body){ui.modalCard.innerHTML=`<div style="display:flex;justify-content:space-between;align-items:center;gap:12px"><div><div class="eyebrow">Mutant Monster Fishing</div><div class="modal-title">${title}</div></div><button class="btn secondary small" data-close>BACK</button></div>${body}`;ui.modal.classList.remove('hidden');}
ui.modal.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-close')){ui.modal.classList.add('hidden');return;}
 if(b.dataset.area!==undefined){const i=+b.dataset.area;if(i<=save.area){save.area=i;persist();ui.modal.classList.add('hidden');toast(`${areas[i][0]} selected`);}else toast(`Beat the ${areas[i-1][0]} boss to unlock this water!`);}
 if(b.dataset.rod!==undefined){const i=+b.dataset.rod;if(save.rods.includes(i)){save.rod=i;persist();toast(`${rods[i][0]} equipped`);}else if(save.cash>=rods[i][1]){save.cash-=rods[i][1];save.rods.push(i);save.rod=i;persist();toast(`${rods[i][0]} purchased!`);}else toast(`Need ${rods[i][1]-save.cash}¢ more`);renderShop();}
});
function renderAreas(){showModal('FISHING AREAS',`<p class="storytext">Defeat each area's boss to open the next water. Your current waters are always available.</p><div class="grid">${areas.map((a,i)=>`<button class="tile ${i===save.area?'selected':''}" data-area="${i}"><h3>${i<save.area?'✅':i===save.area?'📍':'🔒'} ${a[0]}</h3><p>${a[1]}</p><div class="meta">${i<=save.area?'OPEN · BOSS: '+fishNames[i][4].toUpperCase():'LOCKED · BEAT '+fishNames[i-1][4].toUpperCase()}</div></button>`).join('')}</div>`);}
function renderShop(){showModal('ROD SHOP',`<p class="storytext">Better rods make each pull count harder and give you more control over the monsters.</p>${rods.map((r,i)=>{const owned=save.rods.includes(i);return `<div class="rod-row"><div class="rod-icon">${['🪵','🍾','🔩','🟢','⚙️','🌊','🐉','⚡','🪝','☣️'][i]}</div><div class="rod-info"><b>${r[0]} ${save.rod===i?'· EQUIPPED':''}</b><small>Reel power ×${r[2].toFixed(2)} · ${owned?'Owned':r[1]+'¢'}</small><div class="bar"><i style="width:${Math.round(r[2]/2.9*100)}%"></i></div></div><button class="btn ${owned?'secondary':''} small" data-rod="${i}">${owned?(save.rod===i?'ON':'EQUIP'):'BUY'}</button></div>`;}).join('')}`);}
function renderLog(){showModal('MUTANT FIELD LOG',`<p class="storytext"><b>${save.caught.length}/50</b> species discovered · ${save.caught.filter(i=>fishList[i].boss).length}/10 bosses beaten.</p><div class="grid">${fishList.map(f=>{const got=save.caught.includes(f.index);return `<div class="tile" style="cursor:default;opacity:${got?1:.64}"><h3>${got?(f.boss?'☣ ':'🐟 ')+f.name:'???'}</h3><p>${got?`${areas[f.zone][0]} · ${f.rarity} · ${f.size} cm`:`${areas[f.zone][0]} · Undiscovered`}</p><div class="meta">${got?f.value+'¢ VALUE':f.boss?'BOSS CLASS':'UNKNOWN SPECIES'}</div></div>`;}).join('')}</div>`);}
$('#areasBtn').addEventListener('click',renderAreas);$('#rodsBtn').addEventListener('click',renderShop);$('#albumBtn').addEventListener('click',renderLog);
function storyText(){return [`The Spill: The bay's fish are growing teeth. Find out what the lab dumped.`,`Rust Never Sleeps: A signal pulses beneath the old docks. Track its source.`,`Bloom of Doom: A mutant spore colony is swallowing the marsh.`,`Shattered Tide: Something has cracked the reef's glassy heart.`,`Home Below: Lights are on in the drowned suburb. Who is still there?`,`Cold Case: A research vessel vanished in the fjord. Reel in its black box.`,`Hot Pursuit: Follow the thermal plume down to the volcano trench.`,`Lunar Tides: A meteor shower woke an ancient presence in the lake.`,`Into the Void: The signal has a name. And it knows yours.`,`The Last Catch: Face Zanrich and decide the fate of the deep.`][Math.min(save.story,9)];}

