function update(dt){
 if(phase==='waiting'&&elapsed>=biteAt){currentFish=chooseFish();phase='bite';phaseAt=elapsed;ui.action.textContent='REEL!';ui.tension.style.display='none';setStatus(`SOMETHING'S ON! <b>${currentFish.boss?'BOSS CLASS — ':''}${currentFish.name.toUpperCase()}</b><br><span style="color:#a8b99a">Tap and hold REEL to bring it in!</span>`);toast('BITE! SET THE HOOK!');}
 if(phase==='bite'&&elapsed-phaseAt>4.2)loseFish('The mutant stole your bait!');
 if(phase==='reeling'){
  const power=rods[save.rod][2],fight=Math.sin(elapsed*3.1+(currentFish.index||0))*9+Math.sin(elapsed*6.7)*4;
  tension=clamp(tension+(holding?(31+fight)*dt:-26*dt),0,110);
  const green=tension>=30&&tension<=78;
  if(holding&&green)progress+=dt*(18+power*7)*(currentFish.boss?.78:1);
  else if(!holding)progress=Math.max(0,progress-dt*3.5);
  ui.fill.style.width=clamp(tension,0,100)+'%';ui.tensionLabel.textContent=tension>78?'TOO TIGHT! EASE UP':green?'GOOD TENSION · KEEP REELING':'LINE SLACK · PULL!';
  ui.tensionLabel.style.color=tension>78?'#ff7892':green?'#d7f477':'#a7f5e7';
  if(tension>=100){loseFish('SNAP! The line broke!');}
  else if(progress>=100){landFish();}
  else if(elapsed-phaseAt>16){loseFish('The monster escaped into the deep!');}
 }
 if(mode==='pvp'&&phase!=='idle'&&elapsed-phaseAt>5+botScore*1.7&&botScore<3){botScore++;phaseAt=elapsed;toast(`RIVAL LANDED ONE! YOU ${duelScore} – ${botScore}`);if(botScore>=3){mode='free';phase='idle';ui.action.textContent='CAST';setStatus(`DUEL LOST · Rival won ${botScore}–${duelScore}. Try another duel!`);toast('DUEL LOST — REMATCH?');}}
 if(mode==='challenge'&&elapsed-phaseAt>90){if(challengeCatches<3){mode='free';phase='idle';ui.action.textContent='CAST';setStatus(`CHALLENGE OVER · ${challengeCatches}/3 catches. Try again!`);toast('TIME UP!');}else phaseAt=elapsed;}
}
